arguments.command:
cat << 'EOF' > /tmp/test_stackalloc_nint.cs
Span<nint> s = stackalloc nint[4];
s[0] = 42;
s[1] = nint.MaxValue;
s[2] = nint.MinValue;
s[3] = (nint)123456789;

Console.WriteLine($"Length: {s.Length}");
for (int i = 0; i < s.Length; i++)
    Console.WriteLine($"  s[{i}] = {s[i]}");

Console.WriteLine($"nint size: {nint.Size} bytes");
Console.WriteLine("stackalloc Span<nint> works!");
EOF
dotnet run /tmp/test_stackalloc_nint.cs

